13 // AXI Error Slave: This module always responds with an AXI error for transactions that are sent to
14 // it.  This module optionally supports ATOPs if the `ATOPs` parameter is set.
15 
16 module axi_err_slv #(
17   parameter int unsigned          AxiIdWidth  = 0,                    // AXI ID Width
18   parameter type                  req_t       = logic,                // AXI 4 request struct, with atop field
19   parameter type                  resp_t      = logic,                // AXI 4 response struct
20   parameter axi_pkg::resp_t       Resp        = axi_pkg::RESP_DECERR, // Error generated by this slave.
21   parameter int unsigned          RespWidth   = 32'd64,               // Data response width, gets zero extended or truncated to r.data.
22   parameter logic [RespWidth-1:0] RespData    = 64'hCA11AB1EBADCAB1E, // Hexvalue for data return value
23   parameter bit                   ATOPs       = 1'b1,                 // Activate support for ATOPs.  Set to 1 if this slave could ever get an atomic AXI transaction.
24   parameter int unsigned          MaxTrans    = 1                     // Maximum # of accepted transactions before stalling
25 ) (
26   input  logic  clk_i,   // Clock
27   input  logic  rst_ni,  // Asynchronous reset active low
28   input  logic  test_i,  // Testmode enable
29   // slave port
30   input  req_t  slv_req_i,
31   output resp_t slv_resp_o
32 );
33   typedef logic [AxiIdWidth-1:0] id_t;
34   typedef struct packed {
35     id_t           id;
36     axi_pkg::len_t len;
37   } r_data_t;
38 
39   req_t   err_req;
40   resp_t  err_resp;
41 
42   if (ATOPs) begin
43     axi_atop_filter #(
44       .AxiIdWidth       ( AxiIdWidth  ),
45       .AxiMaxWriteTxns  ( MaxTrans    ),
46       .req_t            ( req_t       ),
47       .resp_t           ( resp_t      )
48     ) i_atop_filter (
49       .clk_i,
50       .rst_ni,
51       .slv_req_i  ( slv_req_i   ),
52       .slv_resp_o ( slv_resp_o  ),
53       .mst_req_o  ( err_req     ),
54       .mst_resp_i ( err_resp    )
55     );
56   end else begin
57     assign err_req    = slv_req_i;
58     assign slv_resp_o = err_resp;
59   end
60 
61   // w fifo
62   logic    w_fifo_full, w_fifo_empty;
63   logic    w_fifo_push, w_fifo_pop;
64   id_t     w_fifo_data;
65   // b fifo
66   logic    b_fifo_full, b_fifo_empty;
67   logic    b_fifo_push, b_fifo_pop;
68   id_t     b_fifo_data;
69   // r fifo
70   r_data_t r_fifo_inp;
71   logic    r_fifo_full, r_fifo_empty;
72   logic    r_fifo_push, r_fifo_pop;
73   r_data_t r_fifo_data;
74   // r counter
75   logic    r_cnt_clear, r_cnt_en, r_cnt_load;
76   axi_pkg::len_t r_current_beat;
77   // r status
78   logic    r_busy_d, r_busy_q, r_busy_load;
79 
80   //--------------------------------------
81   // Write Transactions
82   //--------------------------------------
83   // push, when there is room in the fifo
84   assign w_fifo_push        = err_req.aw_valid & ~w_fifo_full;
85   assign err_resp.aw_ready  = ~w_fifo_full;
86 
87   fifo_v3 #(
88     .FALL_THROUGH ( 1'b1      ),
89     .DEPTH        ( MaxTrans  ),
90     .dtype        ( id_t      )
91   ) i_w_fifo (
92     .clk_i      ( clk_i             ),
93     .rst_ni     ( rst_ni            ),
94     .flush_i    ( 1'b0              ),
95     .testmode_i ( test_i            ),
96     .full_o     ( w_fifo_full       ),
97     .empty_o    ( w_fifo_empty      ),
98     .usage_o    (                   ),
99     .data_i     ( err_req.aw.id     ),
100     .push_i     ( w_fifo_push       ),
101     .data_o     ( w_fifo_data       ),
102     .pop_i      ( w_fifo_pop        )
103   );
104 
105   always_comb begin : proc_w_channel
106     err_resp.w_ready  = 1'b0;
107     w_fifo_pop        = 1'b0;
108     b_fifo_push       = 1'b0;
109     if (!w_fifo_empty && !b_fifo_full) begin
110       // eat the beats
111       err_resp.w_ready = 1'b1;
112       // on the last w transaction
113       if (err_req.w_valid && err_req.w.last) begin
114         w_fifo_pop    = 1'b1;
115         b_fifo_push   = 1'b1;
116       end
117     end
118   end
119 
120   fifo_v3 #(
121     .FALL_THROUGH ( 1'b0         ),
122     .DEPTH        ( unsigned'(2) ), // two placed so that w can eat beats if b is not sent
123     .dtype        ( id_t         )
124   ) i_b_fifo (
125     .clk_i      ( clk_i        ),
126     .rst_ni     ( rst_ni       ),
127     .flush_i    ( 1'b0         ),
128     .testmode_i ( test_i       ),
129     .full_o     ( b_fifo_full  ),
130     .empty_o    ( b_fifo_empty ),
131     .usage_o    (              ),
132     .data_i     ( w_fifo_data  ),
133     .push_i     ( b_fifo_push  ),
134     .data_o     ( b_fifo_data  ),
135     .pop_i      ( b_fifo_pop   )
136   );
137 
138   always_comb begin : proc_b_channel
139     b_fifo_pop        = 1'b0;
140     err_resp.b        = '0;
141     err_resp.b.id     = b_fifo_data;
142     err_resp.b.resp   = Resp;
143     err_resp.b_valid  = 1'b0;
144     if (!b_fifo_empty) begin
145       err_resp.b_valid = 1'b1;
146       // b transaction
147       b_fifo_pop = err_req.b_ready;
148     end
149   end
150 
151   //--------------------------------------
152   // Read Transactions
153   //--------------------------------------
154   // push if there is room in the fifo
155   assign r_fifo_push        = err_req.ar_valid & ~r_fifo_full;
156   assign err_resp.ar_ready  = ~r_fifo_full;
157 
158   // fifo data assignment
159   assign r_fifo_inp.id  = err_req.ar.id;
160   assign r_fifo_inp.len = err_req.ar.len;
161 
162   fifo_v3 #(
163     .FALL_THROUGH ( 1'b0      ),
164     .DEPTH        ( MaxTrans  ),
165     .dtype        ( r_data_t  )
166   ) i_r_fifo (
167     .clk_i     ( clk_i        ),
168     .rst_ni    ( rst_ni       ),
169     .flush_i   ( 1'b0         ),
170     .testmode_i( test_i       ),
171     .full_o    ( r_fifo_full  ),
172     .empty_o   ( r_fifo_empty ),
173     .usage_o   (              ),
174     .data_i    ( r_fifo_inp   ),
175     .push_i    ( r_fifo_push  ),
176     .data_o    ( r_fifo_data  ),
177     .pop_i     ( r_fifo_pop   )
178   );
179 
180   always_comb begin : proc_r_channel
181     // default assignments
182     r_busy_d    = r_busy_q;
183     r_busy_load = 1'b0;
184     // r fifo signals
185     r_fifo_pop  = 1'b0;
186     // r counter signals
187     r_cnt_clear = 1'b0;
188     r_cnt_en    = 1'b0;
189     r_cnt_load  = 1'b0;
190     // r_channel
191     err_resp.r        = '0;
192     err_resp.r.id     = r_fifo_data.id;
193     err_resp.r.data   = RespData;
194     err_resp.r.resp   = Resp;
195     err_resp.r_valid  = 1'b0;
196     // control
197     if (r_busy_q) begin
198       err_resp.r_valid = 1'b1;
199       err_resp.r.last = (r_current_beat == '0);
200       // r transaction
201       if (err_req.r_ready) begin
202         r_cnt_en = 1'b1;
203         if (r_current_beat == '0) begin
204           r_busy_d    = 1'b0;
205           r_busy_load = 1'b1;
206           r_cnt_clear = 1'b1;
207           r_fifo_pop  = 1'b1;
208         end
209       end
210     end else begin
211       // when not busy and fifo not empty, start counter err gen
212       if (!r_fifo_empty) begin
213         r_busy_d    = 1'b1;
214         r_busy_load = 1'b1;
215         r_cnt_load  = 1'b1;
216       end
217     end
218   end
219 
220   always_ff @(posedge clk_i, negedge rst_ni) begin
221     if (!rst_ni) begin
222       r_busy_q <= '0;
223     end else if (r_busy_load) begin
224       r_busy_q <= r_busy_d;
225     end
226   end
227 
228   counter #(
229     .WIDTH     ($bits(axi_pkg::len_t))
